action.code:
TreeNode* curr = root;
int outIdx = 0;
for (int i = 0; i < encLen; ++i) {
    int bit = encoded[i];
    if (bit == 0) {
        curr = curr->left;
    } else {
        curr = curr->right;
    }
    if (curr->left == nullptr && curr->right == nullptr) {
        decoded[outIdx++] = curr->val;
        curr = root;
    }
}
decLen = outIdx;
// END_CODE

